/**  https://manwaai.cc/static/js/ch.js?v=202208132
*/

function decode(bytes, key){

return java.createSymmetricCrypto(
	"aes/cbc/pkcs7padding", 
	 key,
	 key
	)
.decrypt(bytes)
}

key = cache.get("manwa_aes_key") || "my2ecret782ecret"

decode(result, key)

