if(need){
java.longToast('请完成搜索验证后点右上角对勾');
var resp=java.startBrowserAwait(java.get('url'),'搜索验证');
var html='';try{html=String(resp.body());}catch(e){html=String(resp);}
java.setContent(html);
c=books();
}
c;
}

