sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

push('榜单', null, 1, 1);
  bd=["综合","新书","完结","男生","女生","收藏"];
    bd.map((title,type)=>{					
			url = `@js:link_Urlpath = "/Book/RankingList";
	   	link_Params =	{"ranking_id":${type+91},"start":(page-1)*20,"limit":20};	
		 	eval(String(source.bookSourceComment));`;

				if(type+1 <= bd.length - bd.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.3);}										
			});

   fl =[["男频","100",
["都市","玄幻","仙侠","灵异","军史","科幻","竞技","N次元"]],
["女频","200",
["现言","古言","幻言","灵异","科幻","青春"]],
["名著","300",
["中国名著","外国名著"]]
];
fl.map([title,gender,list]=>{

	push(title, null, 1, 1);
	  list.map((title,type)=>{
	  	url = `@js:link_Urlpath = "/Book/QueryBookForCtgr";
	   	link_Params =	{"type":${type+1+Number(gender)},"category":0,"serials":"不限","vip":"不限","start":(page-1)*20,"limit":20};	
		 	eval(String(source.bookSourceComment));`;
	if(list.length > 3){
		if(type+1 <= list.length - list.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
				}
				else{ push(title, url, 1, 0.25);}
    	});
	});

JSON.stringify(sort);

source.bookSourceComment:

jm = Object.keys(link_Params).map((key)=>link_Params[key]).join("");
_md5 = String(java.md5Encode(jm));
md5 = _md5.substring(3,_md5.length-5);
api_Params = {
   "ver": "1.6.4",
   "md5": md5
};
body = Object.assign(link_Params, api_Params);
option = {'method':'POST','body':JSON.stringify(body)};
url = link_Urlpath +","+ JSON.stringify(option);

